import{_ as e,c as r,o as t,ag as o}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"簡介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1794112334000}'),i={name:"zh-TW/guide/introduction.md"};function n(s,a,h,l,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to &quot;簡介&quot;">​</a></h1><h2 id="關於-nicasa" tabindex="-1">關於 Nicasa <a class="header-anchor" href="#關於-nicasa" aria-label="Permalink to &quot;關於 Nicasa&quot;">​</a></h2><p>Nicasa 是一款現代桌面圖片檢視與截圖工具，以速度、簡潔和強大的編輯能力為設計目標。它專為 macOS 打造，把順暢、現代的看圖體驗帶到你的桌面。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="🖼️-更好的看圖方式" tabindex="-1">🖼️ <strong>更好的看圖方式</strong> <a class="header-anchor" href="#🖼️-更好的看圖方式" aria-label="Permalink to &quot;🖼️ **更好的看圖方式**&quot;">​</a></h3><p>乾淨專注的介面讓圖片瞬間呈現。沒有干擾，沒有雜亂——只有你的內容，在開啟的那一刻被優雅地呈現。</p><h3 id="📸-截圖與擷取" tabindex="-1">📸 <strong>截圖與擷取</strong> <a class="header-anchor" href="#📸-截圖與擷取" aria-label="Permalink to &quot;📸 **截圖與擷取**&quot;">​</a></h3><p>幾秒內截取螢幕任意區域。快速而精確的截圖工具內建於 Nicasa，儲存與分享視覺靈感從未如此簡單。</p><h3 id="🤖-ai-影像編輯" tabindex="-1">🤖 <strong>AI 影像編輯</strong> <a class="header-anchor" href="#🤖-ai-影像編輯" aria-label="Permalink to &quot;🤖 **AI 影像編輯**&quot;">​</a></h3><p>用強大的 AI 工具增強與修飾圖片。從快速調整到智慧編輯，Nicasa 幫你輕鬆完成影像變身。</p><h3 id="🔍-透明懸浮模式" tabindex="-1">🔍 <strong>透明懸浮模式</strong> <a class="header-anchor" href="#🔍-透明懸浮模式" aria-label="Permalink to &quot;🔍 **透明懸浮模式**&quot;">​</a></h3><p>設計師與繪師的利器：把圖片置頂於所有視窗之上，並可調整透明度——非常適合描圖、參考對照和 UI 比對。</p><h3 id="🌐-chrome-擴充功能整合" tabindex="-1">🌐 <strong>Chrome 擴充功能整合</strong> <a class="header-anchor" href="#🌐-chrome-擴充功能整合" aria-label="Permalink to &quot;🌐 **Chrome 擴充功能整合**&quot;">​</a></h3><p>與 Nicasa Chrome 擴充功能無縫銜接，在一個介面裡檢視任意網站上的全部圖片。隨時擷取、瀏覽並直接在 Nicasa 中開啟圖片，獲得更快、更沉浸的看圖體驗。</p><h3 id="🎨-順暢直觀的設計" tabindex="-1">🎨 <strong>順暢直觀的設計</strong> <a class="header-anchor" href="#🎨-順暢直觀的設計" aria-label="Permalink to &quot;🎨 **順暢直觀的設計**&quot;">​</a></h3><p>由新世代技術驅動，Nicasa 帶來流暢的轉場、清晰的算繪和體貼的互動設計。</p><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><ul><li><strong>作業系統</strong>：macOS 10.13 或更高版本</li><li><strong>記憶體</strong>：最低 4GB RAM，建議 8GB</li><li><strong>儲存空間</strong>：安裝需要 54.5 MB</li><li><strong>顯示</strong>：最低 1280x720 解析度</li></ul><h2 id="支援的語言" tabindex="-1">支援的語言 <a class="header-anchor" href="#支援的語言" aria-label="Permalink to &quot;支援的語言&quot;">​</a></h2><p>Nicasa 支援多種語言，包括英語、簡體中文、繁體中文、日語、法語、韓語、德語、西班牙語、義大利語、越南語、泰語、印地語、土耳其語、俄語、葡萄牙語、荷蘭語、德語（瑞士）、芬蘭語、馬來語、希臘語、挪威語、印尼語、匈牙利語、丹麥語和烏克蘭語。</p><h2 id="開始使用" tabindex="-1">開始使用 <a class="header-anchor" href="#開始使用" aria-label="Permalink to &quot;開始使用&quot;">​</a></h2><p>如果你是 Nicasa 新手，請從<a href="/zh-TW/guide/installation.html">安裝指南</a>開始，讓你的 Mac 跑起這款應用程式。</p>',22)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
